int detect_hamming_single_error(unsigned int codeword, int* error_pos) {
    unsigned int p1 = 0, p2 = 0, p4 = 0;
    for (int i = 1; i <= 7; i++) {
        unsigned int bit = (codeword >> (7 - i)) & 1;
        if (i & 1) p1 ^= bit;
        if (i & 2) p2 ^= bit;
        if (i & 4) p4 ^= bit;
    }
    int syndrome = (p4 << 2) | (p2 << 1) | p1;
    if (error_pos) *error_pos = syndrome;
    return (syndrome != 0);
}

