int detect_luhn_checksum(const char* num_str) {
    int len = 0;
    while (num_str[len] != '\0') len++;
    int sum = 0, alternate = 0;
    for (int i = len - 1; i >= 0; i--) {
        if (num_str[i] < '0' || num_str[i] > '9') continue;
        int d = num_str[i] - '0';
        if (alternate) {
            d *= 2;
            if (d > 9) d -= 9;
        }
        sum += d;
        alternate = !alternate;
    }
    return (sum % 10 == 0);
}

